"""Build public service pages using the existing Raylab brand and catalogue."""
from pathlib import Path
import re,json,html
from service_visuals import render_visual
root=Path(__file__).resolve().parents[3]
dist=root/'web/dist'
index=(dist/'index.html').read_text(encoding='utf-8')
catalog=json.loads((dist/'js/services-data.js').read_text(encoding='utf-8').split('=',1)[1].strip().rstrip(';'))['services']
details={
'odoo':('Tu operación cambia. Tu Odoo también.', 'Adaptamos Odoo a la forma en que trabaja tu empresa: módulos, integraciones y mejoras técnicas con un alcance definido.', ['Un proceso que exige demasiados pasos manuales.','Una integración que necesita compartir información con otra plataforma.','Un módulo o reporte que debe responder a una necesidad específica.'],['Versión y alojamiento de Odoo.','Módulos instalados y descripción del proceso.','Un ejemplo del problema y el resultado esperado.'],['Revisar el proceso','Adaptar Odoo','Validar con tu equipo'],('¿Trabajan con un Odoo que ya está funcionando?','Sí. Revisamos la versión, los módulos y el entorno antes de proponer cambios. La compatibilidad se evalúa para cada instalación.'),('¿Incluye licencias de Odoo?','Las licencias, el alojamiento y los servicios externos se detallan por separado en la propuesta.')),
'web':('Una web que presenta tu negocio y facilita el contacto.', 'Diseñamos páginas corporativas y landing pages con una identidad cuidada, contenido claro y una experiencia adaptable a celulares.', ['Tu negocio necesita una presencia propia en internet.','Tus visitantes no encuentran qué ofreces o cómo contactarte.','Una campaña necesita una página enfocada en un servicio.'],['Objetivo de la página y público al que se dirige.','Logo, servicios, textos y fotografías disponibles.','Dominio y alojamiento, si ya cuentas con ellos.'],['Organizar el contenido','Diseñar la experiencia','Publicar y revisar'],('¿Se verá bien en el celular?','El diseño se adapta a móvil, tablet y escritorio. Revisamos navegación, formularios y tamaños de pantalla antes de la entrega.'),('¿Dominio y hosting están incluidos?','Se acuerdan en la propuesta. Podemos orientar su configuración; los costos de proveedores externos se especifican por separado.')),
'whatsapp':('Tu negocio responde. Tu equipo sigue al mando.', 'Creamos bots y agentes de WhatsApp con información de tu empresa, documentos autorizados y un recorrido claro hacia la atención humana.', ['Recibes preguntas repetidas sobre servicios, horarios o productos.','Necesitas compartir catálogos sin buscarlos en cada conversación.','Quieres registrar consultas en Odoo o derivarlas a tu equipo.'],['Número de WhatsApp y situación actual de su cuenta.','Preguntas frecuentes, catálogo y documentos vigentes.','Reglas para responder, derivar y pausar la automatización.'],['Cliente consulta','Agente orienta','Equipo da seguimiento'],('¿Puedo seguir usando WhatsApp Business?','La coexistencia puede permitirlo mediante una integración compatible. Evaluamos la elegibilidad del número y los requisitos del proveedor antes de conectarlo.'),('¿El agente puede responder cualquier cosa?','Lo configuramos para el contexto del negocio. Debe derivar las consultas que no pueda resolver y no inventar precios, disponibilidad ni condiciones.')),
'microapps':('Un problema concreto. Una herramienta para resolverlo.', 'Desarrollamos aplicaciones pequeñas con una función principal: cotizar, reservar, registrar o simplificar una tarea de tu operación.', ['Una tarea depende de cálculos o registros manuales repetidos.','Necesitas un cotizador con reglas propias.','Una solicitud o reserva necesita un flujo más ordenado.'],['La tarea exacta que quieres resolver.','Datos de entrada, reglas y resultado esperado.','Quién la utilizará y si necesita accesos o integraciones.'],['Definir una tarea','Construir el flujo','Probar con datos reales'],('¿Es un ERP completo?','No. Una microapp se concentra en una necesidad. Si el alcance requiere varios procesos, evaluamos otra solución o una integración con Odoo.'),('¿Puede guardar información?','Sí, si el proyecto lo requiere. Los usuarios, la base de datos, los permisos y las conexiones se definen en el alcance.')),
'ads':('Campañas con dirección. Consultas con seguimiento.', 'Configuramos y gestionamos campañas en Meta Ads y Google Ads, con objetivos, anuncios y medición alineados con tu negocio.', ['Quieres presentar un servicio a una audiencia concreta.','Necesitas organizar campañas que ya están activas.','Buscas conectar tus anuncios con una landing o WhatsApp.'],['Producto o servicio, audiencia y zona de atención.','Acceso autorizado a las cuentas publicitarias.','Presupuesto disponible y materiales del anuncio.'],['Definir el objetivo','Lanzar la campaña','Medir y optimizar'],('¿El presupuesto de anuncios está incluido?','La inversión que cobra Meta o Google es independiente del servicio de gestión. Ambos conceptos se detallan antes de iniciar.'),('¿Garantizan ventas?','No se garantiza una cantidad de ventas. El desempeño depende de la oferta, el presupuesto, la competencia, la página de destino y la atención comercial.')),
'analytics':('Entiende tus visitas. Evalúa tus decisiones.', 'Configuramos Google Analytics 4 y eventos para observar cómo llegan los visitantes y qué acciones realizan en tu página.', ['Tu web recibe visitas pero no sabes de dónde llegan.','Quieres medir formularios o clics hacia WhatsApp.','Necesitas evaluar campañas con una medición acordada.'],['Dirección de la web y accesos de configuración.','Acciones que representan una consulta para tu negocio.','Herramientas actuales y requisitos de consentimiento.'],['Definir eventos','Validar la medición','Revisar los reportes'],('¿Qué acciones se pueden medir?','Por ejemplo, formularios completados y clics de contacto. Revisamos la viabilidad y validamos los eventos acordados en tu sitio.'),('¿Los reportes muestran todas las visitas?','La medición puede verse limitada por consentimiento, bloqueadores y configuración del navegador. Explicamos esas limitaciones al interpretar los datos.')),
'nfc':('Un toque para acercar tu negocio.', 'Configuramos tarjetas y soluciones NFC que llevan a tu contacto, catálogo, menú o enlace para solicitar reseñas reales.', ['Quieres compartir tu contacto sin dictar todos tus datos.','Tu catálogo o menú necesita un acceso directo.','Buscas facilitar que un cliente deje su reseña.'],['Destino del enlace y datos que quieres compartir.','Logo y materiales de tu marca.','Cantidad y formato de tarjetas o soportes.'],['Acercar el celular','Abrir el enlace','Conocer tu negocio'],('¿Funciona en cualquier celular?','La lectura NFC depende del equipo y su configuración. Podemos incluir una alternativa con QR para facilitar el acceso.'),('¿Puedo actualizar el contenido después?','Si el enlace apunta a una página administrable, se puede actualizar su contenido. La administración y el mantenimiento se acuerdan en la propuesta.')),
}
esc=html.escape
head=re.search(r'<!doctype html>.*?</head>',index,re.S|re.I).group()
header=re.search(r'<header>.*?</header>',index,re.S).group()
footer=re.search(r'<footer .*?</footer>',index,re.S).group()
footer=re.sub(r'href="#([^"]+)"',r'href="index.html#\1"',footer)
header=re.sub(r'href="#([^"]+)"',r'href="index.html#\1"',header)
for service in catalog:
 service['category']={'odoo':'Odoo','web':'Páginas web','whatsapp':'Agentes de WhatsApp','microapps':'Microapps','ads':'Meta Ads y Google Ads','analytics':'Analítica y medición','nfc':'Soluciones NFC'}[service['id']]
 key=service['id']; title,description,needs,prepare,flow,faq1,faq2=details[key]
 pagehead=re.sub(r'<title>.*?</title>',lambda m:'<title>'+esc(service['title'].rstrip('.'))+' | Raylab</title>',head)
 pagehead=re.sub(r'<meta name="description" content="[^"]*">',lambda m:'<meta name="description" content="'+esc(description,quote=True)+'">',pagehead)
 pagehead=pagehead.replace('</head>','<link rel="stylesheet" href="css/service-page.css?v=mobile-menu-20261119"><link rel="stylesheet" href="css/service-visuals.css?v=4"></head>')
 cards=''.join('<article><span class="service-step">'+str(i+1).zfill(2)+'</span><h3>'+esc(x)+'</h3><p>'+esc(service['features'][i])+'</p></article>' for i,x in enumerate(flow))
 bullets=lambda xs:'<ul>'+''.join('<li>'+esc(x)+'</li>' for x in xs)+'</ul>'
 faqs=''.join('<details><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>' for q,a in [faq1,faq2])
 related=''.join('<a href="servicio-'+x['id']+'.html">'+esc(x['title'].rstrip('.'))+'</a>' for x in catalog if x['id']!=key)
 page=pagehead+'<body class="service-detail-page" data-service="'+key+'">'+header+'''<main class="wrap service-page-main"><nav class="service-breadcrumb" aria-label="Ruta de navegación"><a href="index.html#servicios">Todos los servicios</a><span aria-hidden="true">/</span><span>'''+esc(service['category'])+'''</span></nav><section class="service-detail-hero"><div><p class="eyebrow">'''+esc(service['category'])+'</p><h1>'+esc(title)+'</h1><p class="service-detail-intro">'+esc(description)+'</p><a class="button" href="#consulta">Conversemos sobre tu proyecto</a></div><aside class="service-scope"><span class="eyebrow">¿CUÁNDO TE PUEDE SERVIR?</span>'+bullets(needs)+'''</aside></section>'''+render_visual(key)+'''<section class="service-detail-block"><div class="service-detail-heading"><h2>Qué podemos construir.<br><em>Con un alcance definido.</em></h2><p>Estas son las capacidades del servicio. Los entregables se acuerdan según tu necesidad.</p></div><div class="service-deliverables">'''+cards+'''</div></section><section class="service-detail-block service-preparation"><div><h2>Empecemos con<br><em>la información correcta.</em></h2><p>No necesitas tener todo resuelto. Esto nos ayuda a entender tu punto de partida.</p></div>'''+bullets(prepare)+'''</section><section class="service-detail-block service-detail-faq"><h2>Antes de empezar.</h2><div>'''+faqs+'''</div></section><section class="service-detail-cta" id="consulta"><p class="eyebrow">TU PROYECTO, EL SIGUIENTE PASO</p><h2>Cuéntanos qué necesita<br><em>tu negocio.</em></h2><p>Revisamos tu caso para definir funciones, entregables y una cotización. Los costos de plataformas, licencias o proveedores se detallan cuando corresponda.</p><a class="button service-whatsapp" href="https://wa.me/51906962740" target="_blank" rel="noopener noreferrer">Consultar por WhatsApp</a></section><nav class="service-related" aria-label="Otros servicios"><h2>También podemos ayudarte con</h2><div>'''+related+'</div></nav></main>'+footer+'<script src="js/whatsapp-core.js"></script><script src="js/service-page.js?v=lighter-20261115"></script><script src="js/service-icons.js?v=lighter-20261115"></script></body></html>'
 page=page.replace('<head>', '<head><base href="../">', 1)
 page=re.sub(r'<nav class="service-breadcrumb".*?</nav>', '<nav class="service-breadcrumb" aria-label="Servicios"><a class="service-back-link" href="index.html#servicios">Ver todos los servicios</a></nav>', page, count=1)
 page=page.replace('<main class="wrap service-page-main">','<main id="main-content" tabindex="-1" class="wrap service-page-main">',1)
 page=page.replace('href="#main-content"','href="servicios/servicio-'+key+'.html#main-content"')
 page=page.replace(header,'<a class="skip-link" href="#main-content">Ir al contenido</a>'+header,1)
 page=re.sub(r'href="#([^\"]*)"',lambda m:f'href="servicios/servicio-{key}.html#{m[1]}"',page)
 (dist/'servicios').mkdir(exist_ok=True)
 (dist/f'servicios/servicio-{key}.html').write_text(page,encoding='utf-8')
print('Built seven service pages')
import runpy
runpy.run_path(str(Path(__file__).with_name('complete-service-guides.py')),run_name='__main__')
